/**
 * "Can my pet eat …?" food lexicon: one entry per food, a verdict per species where a named source covers it.
 *
 * CONTENT RULES (checked by `node scripts/check-foods.mjs`):
 *  - Every verdict paraphrases a page listed in the entry's own `references` (refs = indexes into it) and adds nothing.
 *    Every reference was opened and read when the entry was written (accessed 24–25 October 2026).
 *  - 'ok' or 'treat' is used ONLY when a source says the food may be fed; the note keeps the source's conditions.
 *  - If sources disagree, the more cautious verdict is used and the note says so.
 *  - No doses. Feeding quantities only when a source gives them, quoted with the source named.
 *  - A species without a source is simply left out: the site then says "we have no source for this; ask your vet".
 *  - Purina pages are written by a pet-food manufacturer (vet-staffed); notes say so.
 *  - The toxic-food facts for xylitol, grapes/raisins, onion/garlic/chives, chocolate, macadamia, avocado (birds),
 *    alcohol, raw dough and caffeine keep the ASPCA wording the site used before.
 *  - 'reptile' means bearded dragon or tortoise; each note names which animal its source is about.
 *
 * Anchors on the A–Z pages: English uses `key`; Italian and German use the slugified name unless `anchor` pins one.
 * Pin an anchor before renaming an entry so existing links keep working.
 */
export const LANGS = ['en', 'it', 'de'] as const;
export type Lang = (typeof LANGS)[number];
export const SPECIES = ['dog', 'cat', 'rabbit', 'guinea-pig', 'bird', 'reptile'] as const;
export type Species = (typeof SPECIES)[number];
/** toxic: dangerous, call a vet if eaten · avoid: not recommended · treat: OK in small amounts with the source's conditions · ok: part of a normal diet per the source */
export const VERDICTS = ['toxic', 'avoid', 'treat', 'ok'] as const;
export type Verdict = (typeof VERDICTS)[number];
export type Text = Record<Lang, string>;
/** lang: language of the page when it is not English. maker: written by a pet-food manufacturer. */
export interface Ref { title: string; url: string; lang?: Lang; maker?: boolean }
export interface SpeciesVerdict { v: Verdict; note: Text; refs: number[] }
export interface Food {
  key: string;
  name: Text;
  aliases: Record<Lang, string[]>;
  verdicts: Partial<Record<Species, SpeciesVerdict>>;
  references: Ref[];
  anchor?: Partial<Record<Lang, string>>;
  /** extra tool: 'chocolate' links the chocolate calculator (dogs) */
  tool?: 'chocolate';
}
export const ACCESSED = '2026-10-24';

const t = (en: string, it: string, de: string): Text => ({ en, it, de });
const V = (v: Verdict, refs: number[], note: Text): SpeciesVerdict => ({ v, refs, note });
const N = (en: string[], it: string[], de: string[]): Record<Lang, string[]> => ({ en, it, de });

