// ---------------------------------------------------------------- entries
function F(key: string, name: [string, string, string], aliases: Record<Lang, string[]>, references: Ref[], verdicts: Partial<Record<Species, SpeciesVerdict>>, extra: Partial<Food> = {}): Food {
  return { key, name: t(...name), aliases, references, verdicts, ...extra };
}

