const slug = (s: string) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/ß/g, 'ss').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
/** The stable id of a food's section on the A–Z page in a language (#banana, #anguria, #wassermelone). */
export const anchorOf = (f: Food, lang: Lang) => f.anchor?.[lang] ?? (lang === 'en' ? f.key : slug(f.name[lang]));
/** Folding used for search: lower case, accents and ß removed, typographic apostrophes straightened. */
export const fold = (s: string) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/ß/g, 'ss').replace(/[’`]/g, "'").replace(/\s+/g, ' ').trim();
/** Foods covered for a species, sorted A–Z in a language. */
export const foodsFor = (species: Species, lang: Lang) => FOODS.filter((f) => f.verdicts[species]).sort((a, b) => a.name[lang].localeCompare(b.name[lang], lang));

// ---------------------------------------------------------------- page strings shared by the tool and the A–Z pages
